Blogger Template Style
Name:         Zing Blog
License:      Free Version
Version:      1.0
Author:       Templateify
Author Url:   https://www.templateify.com/
-----------------------------------------------*/

/*-- Customize Options (Start) --
<Variable name="keycolor" description="Main Color" type="color" default="#0088ff" value="#0088ff"/>
<Group description="Theme Options">
 <Variable name="boxed" description="Boxed Mode" type="length" default="0px" min="0px" max="1px" value="0px"/>
    <Variable name="fixedmenu" description="Fixed Menu" type="length" default="1px" min="0px" max="1px" value="1px"/>
    <Variable name="sidebar" description="Left Sidebar" type="length" default="0px" min="0px" max="1px" value="0px"/>
    <Variable name="fixedsidebar" description="Fixed Sidebar" type="length" default="1px" min="0px" max="1px" value="1px"/>
</Group>
<Group description="Theme Widths">
    <Variable name="row.width" description="Container Width" type="length" default="1073px" min="1073px" max="1194px" value="1073px"/>
    <Variable name="sidebar.width" description="Sidebar Width" type="length" default="300px" min="250px" max="336px" value="300px"/>
</Group>
<Group description="Theme Colors">
	<Variable name="background.color" description="Body Background" type="color" default="#e4e4e4"  value="#e4e4e4"/>
    <Variable name="outer.bg" description="Outer Background" type="color" default="#ffffff"  value="#ffffff"/>
    <Variable name="main.color" description="Theme Color" type="color" default="#0088ff" value="#0088ff"/>
    <Variable name="title.color" description="Title Color" type="color" default="#161618" value="#161618"/>
    <Variable name="title.hover.color" description="Title Hover Color" type="color" default="$(main.color)" value="#0088ff"/>
    <Variable name="meta.color" description="Meta Color" type="color" default="#979797" value="#979797"/>
    <Variable name="text.color" description="Text Color" type="color" default="#626262"  value="#626262"/>
    <Variable name="tag.bg" description="Tag Background" type="color" default="$(main.color)" value="#0088ff"/>
    <Variable name="tag.color" description="Tag Color" type="color" default="#FFFFFF"  value="#FFFFFF"/>
</Group>
<Group description="Theme Fonts">
    <Variable name="main.font" description="Site Font" type="font" family="Inter" default="normal 400 14px $(family)" value="normal 400 14px $(family)"/>
    <Variable name="menu.font" description="Menu Font" type="font" family="Inter" default="normal 400 14px $(family)" value="normal 400 14px $(family)"/>
    <Variable name="title.font" description="Title Font" type="font" family="Inter" default="normal 400 14px $(family)" value="normal 400 14px $(family)"/>
    <Variable name="text.font" description="Text Font" type="font" family="Inter" default="normal 400 14px $(family)" value="normal 400 14px $(family)"/>
</Group>
<Group description="Top Bar" selector="nav.topbar-wrap">
    <Variable name="topbar.bg" description="Top Bar Background" type="color" default="#ffffff" value="#ffffff"/>
    <Variable name="topbar.color" description="Top Bar Color" type="color" default="#595d69" value="#595d69"/>
    <Variable name="topbar.hover.color" description="Top Bar Hover Color" type="color" default="#161618" value="#161618"/>
</Group>
<Group description="Site Header" selector="#header-wrapper">
    <Variable name="header.bg" description="Header Background" type="color" default="#FFFFFF" value="#FFFFFF"/>
    <Variable name="header.color" description="Header Color" type="color" default="$(title.color)" value="#161618"/>
    <Variable name="header.hover.color" description="Header Hover Color" type="color" default="$(main.color)" value="#0088ff"/>
</Group>
<Group description="Sub Menu">
    <Variable name="submenu.bg" description="Sub Menu Background" type="color" default="#FFFFFF" value="#FFFFFF"/>
    <Variable name="submenu.color" description="Sub Menu Color" type="color" default="$(title.color)" value="#161618"/>
    <Variable name="submenu.hover.color" description="Sub Menu Hover Color" type="color" default="$(main.color)" value="#0088ff"/>
</Group>
<Group description="Mega Menu">
    <Variable name="mega.bg" description="Mega Menu Background" type="color" default="$(submenu.bg)" value="#FFFFFF"/>
    <Variable name="mega.color" description="Mega Menu Color" type="color" default="$(submenu.color)" value="#161618"/>
    <Variable name="mega.hover.color" description="Mega Menu Hover Color" type="color" default="$(main.color)" value="#0088ff"/>
    <Variable name="mega.meta.color" description="Mega Meta Color" type="color" default="#979797" value="#979797"/>
</Group>
<Group description="Mobile Menu">
    <Variable name="mobilemenu.bg" description="Mobile Menu Background" type="color" default="#ffffff" value="#FFFFFF"/>
    <Variable name="mobilemenu.color" description="Mobile Menu Color" type="color" default="$(title.color)" value="#161618"/>
    <Variable name="mobilemenu.hover.color" description="Mobile Menu Hover Color" type="color" default="$(main.color)" value="#0088ff"/>
</Group>
<Group description="Theme Widgets" select="#sidebar">
    <Variable name="widget.title.color" description="Title Color" type="color" default="#16161a" value="#16161a"/>
</Group>
<Group description="Video Widget" select="div.video-style">
    <Variable name="video.widget.bg" description="Widget Background" type="color" default="#222226" value="#222226"/>
    <Variable name="video.widget.color" description="Title Color" type="color" default="#FFFFFF" value="#FFFFFF"/>
    <Variable name="video.widget.hover.color" description="Title Hover Color" type="color" default="$(main.color)" value="#0088ff"/>
    <Variable name="video.widget.meta.color" description="Meta Color" type="color" default="#AAAAAA" value="#AAAAAA"/>
</Group>
<Group description="Post Styles" select="#main">
    <Variable name="itempost.title.size" description="Title Font Size" type="length" default="35px" min="20px" max="50px" value="35px"/>
    <Variable name="itempost.content.size" description="Text Font Size" type="length" default="15px" min="12px" max="20px" value="15px"/>
</Group>
<Group description="Post Options" select="#main">
    <Variable name="headerad.onpost" description="Header ADS" type="length" default="1px" min="0px" max="1px" value="1px"/>
    <Variable name="breadcrumb" description="Post Breadcrumbs" type="length" default="1px" min="0px" max="1px" value="1px"/>
    <Variable name="cmm.count" description="Comments Count" type="length" default="1px" min="0px" max="1px" value="1px"/>
    <Variable name="postnav" description="Post Navigation" type="length" default="1px" min="0px" max="1px" value="1px"/>
    <Variable name="footerad.onpost" description="Footer ADS" type="length" default="1px" min="0px" max="1px" value="1px"/>
</Group>
<Group description="Theme Footer" selector="#footer-wrapper">
    <Variable name="footer.bg" description="Footer Background" type="color" default="#161618" value="#161618"/>
    <Variable name="footer.color" description="Footer Color" type="color" default="#FFFFFF" value="#FFFFFF"/>
    <Variable name="footer.hover.color" description="Footer Hover Color" type="color" default="$(main.color)" value="#0088ff"/>
    <Variable name="footer.meta.color" description="Footer Meta Color" type="color" default="#AAAAAA" value="#AAAAAA"/>
    <Variable name="footer.text.color" description="Footer Text Color" type="color" default="#AAAAAA" value="#AAAAAA"/>
</Group>
<Group description="Footer Bar" selector="div.footer-bar">
    <Variable name="footerbar.bg" description="Footer Bar Background" type="color" default="#09090A" value="#09090A"/>
    <Variable name="footerbar.color" description="Footer Bar Color" type="color" default="#FFFFFF" value="#FFFFFF"/>
    <Variable name="footerbar.hover.color" description="Footer Bar Hover Color" type="color" default="$(main.color)" value="#0088ff"/>
</Group>
<Group description="Cookie Consent" selector="#zingblog-pro-cookie-consent">
    <Variable name="cookie.bg" description="Cookie Background" type="color" default="#FFFFFF" value="#FFFFFF"/>
    <Variable name="cookie.color" description="Cookie Text Color" type="color" default="$(text.color)" value="#626262"/>
</Group>
<Group description="Theme Buttons">
    <Variable name="button.bg" description="Button Background" type="color" default="$(main.color)" value="#0088ff"/>
    <Variable name="button.color" description="Button Color" type="color" default="#FFFFFF" value="#FFFFFF"/>
    <Variable name="button.hover.bg" description="Button Hover Background" type="color" default="#1870EB" value="#1870EB"/>
    <Variable name="button.hover.color" description="Button Hover Color" type="color" default="#FFFFFF" value="#FFFFFF"/>
</Group>
<Group description="Theme Fonts (Reset)">
    <!-- Site Font -->
    <Variable name="mainfont.italic" description="Main Font Italic" type="font" default="italic 400 14px $(main.font.family)" value="italic 400 14px $(family)"/>
    <Variable name="mainfont.medium" description="Main Font Medium" type="font" default="normal 500 14px $(main.font.family)" value="normal 500 14px $(family)"/>
    <Variable name="mainfont.mediumitalic" description="Main Font Medium Italic" type="font" default="italic 500 14px $(main.font.family)" value="italic 500 14px $(family)"/>
    <Variable name="mainfont.sb" description="Main Font SemiBold" type="font" default="normal 600 14px $(main.font.family)" value="normal 600 14px $(family)"/>
    <Variable name="mainfont.sbitalic" description="Main Font SemiBold Italic" type="font" default="italic 600 14px $(main.font.family)" value="italic 600 14px $(family)"/>
    <Variable name="mainfont.bold" description="Main Font Bold" type="font" default="normal 700 14px $(main.font.family)" value="normal 700 14px $(family)"/>
    <Variable name="mainfont.bolditalic" description="Main Font Bold Italic" type="font" default="italic 700 14px $(main.font.family)" value="italic 700 14px $(family)"/>
    <!-- Menu Font -->
    <Variable name="menufont.italic" description="Menu Font Italic" type="font" default="italic 400 14px $(menu.font.family)" value="italic 400 14px $(family)"/>
    <Variable name="menufont.bold" description="Menu Font Bold" type="font" default="normal 700 14px $(menu.font.family)" value="normal 700 14px $(family)"/>
    <Variable name="menufont.bolditalic" description="Menu Font Bold Italic" type="font" default="italic 700 14px $(menu.font.family)" value="italic 700 14px $(family)"/>
    <!-- Title Font -->
    <Variable name="titlefont.italic" description="Title Font Italic" type="font" default="italic 400 14px $(title.font.family)" value="italic 400 14px $(family)"/>
    <Variable name="titlefont.medium" description="Title Font Medium" type="font" default="normal 500 14px $(title.font.family)" value="normal 500 14px $(family)"/>
    <Variable name="titlefont.mediumitalic" description="Title Font Medium Italic" type="font" default="italic 500 14px $(title.font.family)" value="italic 500 14px $(family)"/>
    <Variable name="titlefont.sb" description="Title Font SemiBold" type="font" default="normal 600 14px $(title.font.family)" value="normal 600 14px $(family)"/>
    <Variable name="titlefont.sbitalic" description="Title Font SemiBold Italic" type="font" default="italic 600 14px $(title.font.family)" value="italic 600 14px $(family)"/>
    <Variable name="titlefont.bold" description="Title Font Bold" type="font" default="normal 700 14px $(title.font.family)" value="normal 700 14px $(family)"/>
    <Variable name="titlefont.bolditalic" description="Title Font Bold Italic" type="font" default="italic 700 14px $(title.font.family)" value="italic 700 14px $(family)"/>
    <!-- Text Font -->
    <Variable name="textfont.italic" description="Text Font Italic" type="font" default="italic 400 14px $(text.font.family)" value="italic 400 14px $(family)"/>
    <Variable name="textfont.bold" description="Text Font Bold" type="font" default="normal 700 14px $(text.font.family)" value="normal 700 14px $(family)"/>
    <Variable name="textfont.bolditalic" description="Text Font Bold Italic" type="font" default="italic 700 14px $(text.font.family)" value="italic 700 14px $(family)"/>
</Group>
<Variable name="body.background" description="Background" type="background" color="$(background.color)" default="$(color) none repeat fixed top left" value="$(color) none repeat fixed top left"/>
<Variable name="body.background.color" description="Comments Background" hideEditor="true" type="color" default="transparent"  value="transparent"/>
<Variable name="body.title.color" description="Comments Color" hideEditor="true" type="color" default="$(title.color)" value="#161618"/>
<Variable name="body.text.color" description="Comments Text Color" hideEditor="true" type="color" default="$(text.color)"  value="#626262"/>
<Variable name="body.link.color" description="Comments Link Color" hideEditor="true" type="color" default="$(main.color)"  value="#0088ff"/>
<Variable name="body.text.font" description="Comments Font 1" hideEditor="true" type="font" default="normal 400 15px roboto, Arial, sans-serif !important"  value="normal 400 15px roboto, Arial, sans-serif !important"/>
<Variable name="body.action.font.large" description="Comments Font 2" hideEditor="true" type="font" default="normal 700 15px roboto, Arial, sans-serif !important"  value="normal 700 15px roboto, Arial, sans-serif !important"/>
-- Customize Options (End) --*/

