/*-- CSS Variables --*/
:root{
--body-font:'$(main.font.family)', Arial, sans-serif;
--menu-font:'$(menu.font.family)', Arial, sans-serif;
--title-font:'$(title.font.family)', Arial, sans-serif;
--text-font:'$(text.font.family)', Arial, sans-serif;
--body-bg-color:$(background.color);
--body-bg:$(body.background);
--outer-bg:$(outer.bg);
--main-color:$(main.color);
--title-color:$(title.color);
--title-hover-color:$(title.hover.color);
--meta-color:$(meta.color);
--text-color:$(text.color);
--tag-bg:$(tag.bg);
--tag-color:$(tag.color);
--topbar-bg:$(topbar.bg);
--topbar-color:$(topbar.color);
--topbar-hover-color:$(topbar.hover.color);
--header-bg:$(header.bg);
--header-color:$(header.color);
--header-hover-color:$(header.hover.color);
--submenu-bg:$(submenu.bg);
--submenu-color:$(submenu.color);
--submenu-hover-color:$(submenu.hover.color);
--mega-bg:$(mega.bg);
--mega-color:$(mega.color);
--mega-hover-color:$(mega.hover.color);
--mega-meta-color:$(mega.meta.color);
--mobilemenu-bg:$(mobilemenu.bg);
--mobilemenu-color:$(mobilemenu.color);
--mobilemenu-hover-color:$(mobilemenu.hover.color);
--widget-title-color:$(widget.title.color);
--video-widget-bg:$(video.widget.bg);
--video-widget-color:$(video.widget.color);
--video-widget-hover-color:$(video.widget.hover.color);
--video-widget-meta-color:$(video.widget.meta.color);
--footer-bg:$(footer.bg);
--footer-color:$(footer.color);
--footer-hover-color:$(footer.hover.color);
--footer-meta-color:$(footer.meta.color);
--footer-text-color:$(footer.text.color);
--footerbar-bg:$(footerbar.bg);
--footerbar-color:$(footerbar.color);
--footerbar-hover-color:$(footerbar.hover.color);
--cookie-bg:$(cookie.bg);
--cookie-color:$(cookie.color);
--button-bg:$(button.bg);
--button-color:$(button.color);
--button-hover-bg:$(button.hover.bg);
--button-hover-color:$(button.hover.color);
--title-font-weight: 700;
--gray-bg:rgba(155,170,175,0.12);
--border-color:rgba(155,155,155,0.15);
--widget-bg:rgba(33, 99, 232, 0.1);
--radius:2px;
--widget-shadow:0 0 5px rgba(0,0,0,0.01);
--avatar-shadow:0px 1px 4px rgba(0,0,0,0.05);
}
html.is-dark{
--body-bg-color:#39393a;
--body-bg:$(body.background);
--outer-bg:#222226;
--title-color:#f6f7f8;
--title-hover-color:$(main.color);
--meta-color:#aaa;
--text-color:#d4d6d8;
--tag-bg:$(tag.bg);
--tag-color:$(tag.color);
--topbar-bg:#09090a;
--topbar-color:#f6f7f8;
--topbar-hover-color:$(main.color);
--header-bg:#161618;
--header-color:#f6f7f8;
--header-hover-color:$(main.color);
--submenu-bg:#09090a;
--submenu-color:#f6f7f8;
--submenu-hover-color:$(main.color);
--mega-bg:#09090a;
--mega-color:#f6f7f8;
--mega-hover-color:$(main.color);
--mega-meta-color:#aaaaaa;
--mobilemenu-bg:#222226;
--mobilemenu-color:#f6f7f8;
--mobilemenu-hover-color:$(main.color);
--widget-title-bg:#161618;
--widget-title-color:#f6f7f8;
--video-widget-bg:#161618;
--video-widget-color:#f6f7f8;
--video-widget-hover-color:$(main.color);
--video-widget-meta-color:#aaa;
--footer-bg:#161618;
--footer-color:#f6f7f8;
--footer-hover-color:$(main.color);
--footer-meta-color:#aaa;
--footer-text-color:#aaa;
--footerbar-bg:#09090a;
--footerbar-color:#f6f7f8;
--footerbar-hover-color:$(main.color);
--cookie-bg:#09090a;
--cookie-color:#d4d6d8;
--button-bg:$(main.color);
--button-color:#ffffff;
--button-hover-bg:$(button.hover.bg);
--button-hover-color:$(button.hover.color);
--widget-bg:#202024;
--gray-bg:rgba(255,255,255,0.03);
--border-color:rgba(255,255,255,0.05);
}
html.rtl{
--body-font:'Cairo',Arial,sans-serif;
--menu-font:'Cairo',Arial,sans-serif;
--title-font:'Cairo',Arial,sans-serif;
--text-font:'Cairo',Arial,sans-serif;
}

/*-- Reset CSS --*/
 html,body,a,abbr,acronym,address,applet,b,big,blockquote,caption,center,cite,code,dd,del,dfn,div,dl,dt,em,fieldset,font,form,input,button,h1,h2,h3,h4,h5,h6,i,iframe,img,ins,kbd,label,legend,li,object,p,pre,q,s,samp,small,span,strike,strong,sub,sup,table,tbody,td,tfoot,th,thead,tr,tt,u,ul,var{
    padding:0;
    margin:0;
    border:0;
    outline:none;
    vertical-align:baseline;
    background:0 0;
    text-decoration:none
}
dl,ul{
    list-style-position:inside;
    list-style:none
}
ul li{
    list-style:none
}
caption{
    text-align:center
}
img{
    border:none;
    position:relative
}
a,a:visited{
    text-decoration:none
}
.post-body a:visited {
    color:blue;
}
.clearfix{
    clear:both
}
.section,.widget,.widget ul{
    margin:0;
    padding:0
}
a{
    color:var(--main-color)
}
a img{
    border:0
}
abbr{
    text-decoration:none
}
.separator a{
    text-decoration:none!important;
    clear:none!important;
    float:none!important;
    margin-left:0!important;
    margin-right:0!important
}
#Navbar1,#navbar-iframe,.widget-item-control,a.quickedit,.home-link,.feed-links{
    display:none!important
}
.center{
    display:table;
    margin:0 auto;
    position:relative
}
.widget > h2,.widget > h3{
    display:none
}
.widget iframe,.widget img{
    max-width:100%
}
button,input,select,textarea{
    background:transparent;
    font-family:var(--body-font);
    -webkit-appearance:none;
    -moz-appearance:none;
    appearance:none;
    outline:none;
    border-radius:0
}
button{
    cursor:pointer
}
input[type="search"]::-webkit-search-cancel-button{
    -webkit-appearance:none
}
/*-- Style CSS --*/
 *{
    box-sizing:border-box
}
 html{
    position:relative;
    word-break:break-word;
    word-wrap:break-word;
    text-rendering:optimizeLegibility;
    -webkit-font-smoothing:antialiased;
    -webkit-text-size-adjust:100%
}
 body{
    position:relative;
    background:var(--body-bg);
    background-color:var(--body-bg-color);
    font-family:var(--body-font);
    font-size:14px;
    color:var(--text-color);
    font-weight:400;
    font-style:normal;
    line-height:1.4em
}
 .rtl{
    direction:rtl
}
 h1,h2,h3,h4,h5,h6{
    font-family:var(--title-font);
    font-weight:700
}
 a,input,button{
    transition:all .0s ease
}
 #outer-wrapper{
    position:relative;
    overflow:hidden;
    width:100%;
    max-width:100%;
    background-color:var(--outer-bg);
    margin:0 auto;
    padding:0
}
 .is-boxed #outer-wrapper{
    width:$(row.width + 60px);
    max-width:100%;
    box-shadow:0 0 20px rgba(0,0,0,0.1)
}
 .is-dark .is-boxed #outer-wrapper{
    box-shadow:0 0 20px rgba(0,0,0,0.3)
}
 .container{
    position:relative
}
 .row-x1{
    width:$(row.width);
    max-width:100%
}
 .row-x2{
    width:100%
}
 .flex-c{
    display:flex;
    justify-content:center
}
 .flex-col{
    display:flex;
    flex-direction:column
}
 .flex-sb{
    display:flex;
    justify-content:space-between
}
 #content-wrapper{
    float:left;
    width:100%;
    overflow:hidden;
    padding:30px 0
}
 .is-left #content-wrapper > .container,.rtl .is-right #content-wrapper > .container{
    flex-direction:row-reverse
}
 .rtl .is-left #content-wrapper > .container{
    flex-direction:row
}
 .theiaStickySidebar:before,.theiaStickySidebar:after{
    content:'';
    display:table;
    clear:both
}
 #main-wrapper{
    position:relative;
    width:calc(100% - $(sidebar.width + 30px))
}
 .no-sidebar #main-wrapper{
    width:100%
}
 #sidebar-wrapper{
    position:relative;
    width:$(sidebar.width)
}
 .no-sidebar #sidebar-wrapper{
    display:none
}
 .entry-image-wrap,.author-avatar-wrap,.comments .avatar-image-container{
    display:block;
    position:relative;
    overflow:hidden;
    background-color:var(--gray-bg);
    z-index:5;
    color:transparent
}
 .entry-image,.author-avatar{
    display:block;
    position:relative;
    width:100%;
    height:100%;
    background-size:cover;
    background-position:center center;
    background-repeat:no-repeat;
    z-index:1;
    opacity:0;
    transition:opacity .35s ease,filter 0s ease
}
 .entry-image.templateify-lazy,.author-avatar.templateify-lazy{
    opacity:1
}
 .entry-image-wrap:hover .entry-image,.cs:hover .entry-image-wrap .entry-image{
    filter:brightness(1.03)
}
 .entry-image-wrap.is-video:after{
    display:flex;
    position:absolute;
    content:'\e037';
    top:50%;
    right:50%;
    width:38px;
    height:27px;
    background-color:rgba(0,0,0,0.5);
    font-family:'Material Icons Round';
    font-size:25px;
    color:#fff;
    font-weight:400;
    align-items:center;
    justify-content:center;
    z-index:5;
    transform:translate(50%,-50%);
    box-sizing:border-box;
    padding:0 0 0 1px;
    margin:0;
    border-radius:6px;
    box-shadow:0 1px 3px 0 rgba(0,0,0,0.1)
}
 .entry-image-wrap.sz-1.is-video:after{
    transform:translate(50%,-50%) scale(.7)
}
 .entry-image-wrap.sz-2.is-video:after{
    transform:translate(50%,-50%) scale(.8)
}
 .entry-image-wrap.is-video:hover:after,.cs:hover .entry-image-wrap.is-video:after{
    background-color:#f50000
}
 .cs .entry-image-wrap.is-video:after{
    top:15px;
    right:15px;
    transform:translate(0)
}
 .rtl .cs .entry-image-wrap.is-video:after{
    left:15px;
    right:unset
}
 .entry-header{
    display:flex;
    flex-direction:column
}
 .entry-category{
    display:flex;
    align-items:center;
    height:16px;
    background-color:var(--tag-bg);
    font-size:10px;
    color:var(--tag-color);
    font-weight:400;
    text-transform:uppercase;
    line-height:1;
    padding:0 6px
}
 .entry-image-wrap .entry-category{
    position:absolute;
    left:0px;
    bottom:0;
    z-index:2
}
 .rtl .entry-image-wrap .entry-category{
    left:unset;
    right:0
}
 .entry-title{
    color:var(--title-color);
    font-weight:var(--title-font-weight);
    line-height:1.3em
}
 .entry-title a{
    display:block;
    color:var(--title-color)
}
 .entry-title a:hover{
    color:var(--title-hover-color)
}
 .entry-meta{
    display:flex;
    font-size:12px;
    color:var(--meta-color);
    font-weight:400;
    margin:4px 0 0
}
 .entry-meta .mi{
    display:flex
}
 .entry-meta .mi,.entry-meta .sp{
    margin:0 4px 0 0
}
 .rtl .entry-meta .mi,.rtl .entry-meta .sp{
    margin:0 0 0 4px
}
 .entry-meta .author-name{
    color:var(--main-color);
    font-weight:600
}
 .excerpt{
    font-family:var(--text-font);
    line-height:1.5em
}
 .cs .entry-inner{
    display:block;
    position:relative;
    width:100%;
    height:100%;
    overflow:hidden
}
 .before-mask:before{
    content:'';
    position:absolute;
    left:0;
    right:0;
    bottom:0;
    height:80%;
    background-image:linear-gradient(to bottom,rgba(0,0,0,0) 25%,rgba(0,0,0,0.5));
    -webkit-backface-visibility:hidden;
    backface-visibility:hidden;
    z-index:2;
    opacity:1;
    margin:0;
    transition:opacity .25s ease
}
 .entry-info{
    position:absolute;
    left:0;
    bottom:0;
    width:100%;
    background:linear-gradient(to bottom,rgba(0,0,0,0),rgba(0,0,0,0.5));
    overflow:hidden;
    z-index:10;
    padding:15px
}
 .entry-info .entry-title{
    color:#fff;
    text-shadow:0 1px 2px rgba(0,0,0,0.1)
}
 .entry-info .entry-meta{
    color:#c5c5ca;
    text-shadow:0 1px 2px rgba(0,0,0,0.1)
}
 .entry-info .entry-meta .author-name{
    color:#d5d5da;
    font-weight:500
}
 .entry-info .entry-category{
    width:-moz-fit-content;
    width:fit-content;
    margin:0 0 10px
}
 .btn{
    position:relative;
    border-radius:var(--radius)
}
 .error-msg{
    display:flex;
    align-items:center;
    font-size:14px;
    color:var(--meta-color);
    padding:20px 0;
    font-weight:400
}
 .loader{
    position:relative;
    width:100%;
    height:100%;
    overflow:hidden;
    display:flex;
    align-items:center;
    justify-content:center;
    margin:0
}
 .loader:after{
    content:'';
    display:block;
    width:30px;
    height:30px;
    box-sizing:border-box;
    margin:0;
    border:2px solid var(--main-color);
    border-right-color:var(--border-color);
    border-radius:100%;
    animation:spinner .65s infinite linear;
    transform-origin:center
}
 @keyframes spinner{
    0%{
        -webkit-transform:rotate(0deg);
        transform:rotate(0deg)
    }
    to{
        -webkit-transform:rotate(1turn);
        transform:rotate(1turn)
    }
}
 .social a:before{
    display:block;
    font-family:'Font Awesome 5 Brands';
    font-style:normal;
    font-weight:400
}
 .social .rss a:before,.social .share a:before,.social .email a:before,.social .external-link a:before{
    content:'\e0e5';
    font-family:'Material Icons Round'
}
 .social .share a:before{
    content:'\e80d'
}
 .social .email a:before{
    content:'\e0be'
}
 .social .external-link a:before{
    content:'\e89e'
}
 .social-bg .blogger a,.social-bg-hover .blogger a:hover{
    background-color:#ff5722
}
 .social-bg .apple a,.social-bg-hover .apple a:hover{
    background-color:#333
}
 .social-bg .amazon a,.social-bg-hover .amazon a:hover{
    background-color:#fe9800
}
 .social-bg .microsoft a,.social-bg-hover .microsoft a:hover{
    background-color:#0067B8
}
 .social-bg .facebook a,.social-bg .facebook-f a,.social-bg-hover .facebook a:hover,.social-bg-hover .facebook-f a:hover{
    background-color:#3b5999
}
 .social-bg .twitter a,.social-bg-hover .twitter a:hover{
