 .header-header{
    
}
 .header-inner.is-fixed{
    position:fixed;
    top:-60px;
    left:0;
    width:100%;
    z-index:990;
    backface-visibility:hidden;
    visibility:hidden;
    opacity:0;
    transition:all .25s ease
}
 .header-inner.is-fixed.show{
    top:0;
