    box-shadow:0 1px 2px rgba(0,0,0,0.1),0 5px 10px 0 rgba(0,0,0,0.1)
}
 .rtl #zingblog-pro-main-nav ul > li > ul,.rtl #zingblog-pro-main-nav ul > li > .ul{
