    padding:0 16px 0 13px
}
 .mobile-menu-toggle:after{
    content:'\e5d2';
    font-family:'Material Icons Round';
    font-weight:400
}
 .mobile-menu-toggle:hover{
    color:var(--header-hover-color)
}
 .toggle-wrap{
    background-color:var(--header-bg);
    display:flex;
    align-items:center;
    z-index:20
}
 .darkmode-toggle{
    display:flex;
    align-items:center;
    position:relative;
    width:34px;
    height:20px;
    background-color:var(--gray-bg);
    font-size:12px;
    color:var(--header-color);
    margin:0 15px 0 0;
    border-radius:20px
}
 .rtl .darkmode-toggle{
    margin:0 0 0 15px
}
 .darkmode-toggle:before{
    position:absolute;
    left:2px;
    content:'\e518';
    font-family:'PBT Icons';
    width:16px;
    height:16px;
    background-color:var(--header-bg);
    flex-shrink:0;
    font-weight:400;
    line-height:16px;
    text-align:center;
    z-index:2;
    border-radius:50%;
    box-shadow:0 0 2px rgba(0,0,0,0.1);
    transition:left .17s ease
}
 .is-dark .darkmode-toggle:before{
    content:'\ea46';
    left:16px
}
 .rtl .darkmode-toggle:before{
    left:16px
}
 .rtl.is-dark .darkmode-toggle:before{
    left:2px
}
 .darkmode-toggle:after{
    position:absolute;
    right:4px;
    content:'\ea46';
    font-family:'Material Icons Round';
    width:10px;
    height:10px;
    flex-shrink:0;
    font-size:8px;
    font-weight:400;
    line-height:10px;
    text-align:center;
    opacity:.5;
    transition:right .17s ease
}
 .is-dark .darkmode-toggle:after{
    content:'\e518';
    right:20px
}
 .rtl .darkmode-toggle:after{
    right:20px
}
 .rtl.is-dark .darkmode-toggle:after{
    right:4px
}
