    width:300px;
    height:100%;
    top:0;
    left:0;
    bottom:0;
    background-color:var(--mobilemenu-bg);
    overflow:hidden;
    z-index:1010;
    left:0;
    -webkit-transform:translateX(-100%);
    transform:translateX(-100%);
    visibility:hidden;
    box-shadow:3px 0 10px rgba(0,0,0,0.1);
    transition:all .25s ease
}
 .rtl #slide-menu{
    left:unset;
    right:0;
    -webkit-transform:translateX(100%);
    transform:translateX(100%)
}
 .nav-active #slide-menu,.rtl .nav-active #slide-menu{
