@keyframes pulse{
    0%{
        opacity:.8;
        transform:scale(0.8)
    }
    100%{
        opacity:0;
        transform:scale(4)
    }
}
 .ticker .widget-title .title:before,.ticker .widget-title .title:after{
    content:'';
    position:absolute;
    left:0;
    width:4px;
    height:4px;
    background-color:currentColor;
    border-radius:50%
}
