    left:unset;
    right:0;
    transform:translate3d(-10px,0,0)
}
 .ticker-item.active{
    opacity:1;
    visibility:visible;
    transform:translate3d(0,0,0);
    pointer-events:initial
}
 .ticker-item .entry-title{
