    resize:vertical;
    padding:10px
}
 .contact-form-widget .cf-s::placeholder{
    color:var(--text-color);
    opacity:.9
}
 .contact-form-widget .cf-s:focus{
    border-color:var(--main-color)
}
 .contact-form-button-submit{
    float:left;
    width:100%;
    height:34px;
    background-color:var(--button-bg);
    font-family:inherit;
    font-size:14px;
    color:var(--button-color);
    font-weight:400;
    cursor:pointer;
    padding:0 20px;
    border:0;
    border-radius:var(--radius)
}
 .contact-form-button-submit:hover{
    background-color:var(--button-hover-bg);
    color:var(--button-hover-color)
}
 .contact-form-widget p{
    margin:0
}
 .contact-form-widget .contact-form-error-message-with-border,.contact-form-widget .contact-form-success-message-with-border{
    float:left;
    width:100%;
    background-color:rgba(0,0,0,0);
    font-size:13px;
    color:#e74c3c;
    text-align:left;
    line-height:1;
    margin:10px 0 0;
    border:0
}
 .contact-form-widget .contact-form-success-message-with-border{
    color:#27ae60
}
 .rtl .contact-form-error-message-with-border,.rtl .contact-form-success-message-with-border{
    text-align:right
}
 .contact-form-cross{
    cursor:pointer;
    margin:0 0 0 3px
}
 .rtl .contact-form-cross{
    margin:0 3px 0 0
}
 .Attribution a{
    display:flex;
    align-items:center;
    font-size:14px;
    color:var(--title-color);
    font-weight:var(--title-font-weight)
}
 .Attribution a > svg{
    width:16px;
    height:16px;
    fill:var(--main-color);
    margin:0 4px 0 0
}
 .rtl .Attribution a > svg{
    margin:0 0 0 4px
}
 .Attribution a:hover{
    color:var(--title-hover-color)
}
 .Attribution .copyright{
    font-size:12px;
    color:var(--meta-color);
    padding:0 20px;
    margin:2px 0 0
}
 #google_translate_element{
    position:relative;
    overflow:hidden
}
 .Stats .text-counter-wrapper{
    display:flex;
    align-items:center;
    font-size:18px;
    color:var(--meta-color);
    font-weight:700;
    text-transform:uppercase;
    line-height:1;
    margin:0
}
 .Stats .text-counter-wrapper:before{
    content:'\e202';
    font-family:'Material Icons Round';
    font-size:22px;
    color:var(--title-color);
    font-weight:400;
    margin:0 4px 0 0
}
 .rtl .Stats .text-counter-wrapper:before{
    margin:0 0 0 4px
}
 .ReportAbuse > h3{
    display:flex;
    font-size:14px;
    font-weight:400
}
 .ReportAbuse > h3:before{
    content:'\e002';
    font-family:'Material Icons Round';
    font-size:18px;
    color:var(--main-color);
    margin:0 3px 0 0
}
 .rtl .ReportAbuse > h3:before{
    margin:0 0 0 3px
}
 .ReportAbuse > h3 a:hover{
    text-decoration:underline
}
 #footer-ads-wrap{
    float:left;
    width:100%
}
 .footer-ads .widget{
    position:relative;
    margin:0 0 30px
}
 #footer-wrapper{
    position:relative;
    float:left;
    width:100%;
    background-color:var(--footer-bg);
    box-shadow:0 0 10px rgba(0,0,0,0.1)
}
 .primary-footer{
    --title-color:var(--footer-color);
    --title-hover-color:var(--footer-hover-color);
    --meta-color:var(--footer-meta-color);
    --text-color:var(--footer-text-color);
    --title-font-weight:600
}
 .footer-widgets{
    display:grid;
    grid-template-columns:repeat(3,1fr);
    grid-gap:30px;
    padding:40px 0
}
 .footer-widgets.has-border{
    border-top:1px solid var(--border-color)
}
 .footer-section{
    display:grid;
    grid-template-columns:1fr;
    align-content:start;
    grid-gap:30px
}
 .footer-section > .widget{
    display:flex;
    flex-direction:column
}
 .footer-section .widget > .widget-title{
    margin:0 0 20px
}
 .footer-section .widget-title > .title{
    font-size:15px;
    color:var(--title-color);
    font-weight:600;
    text-transform:uppercase
}
 .primary-footer .contact-form-widget .cf-s,.primary-footer .BlogSearch .search-form{
    background-color:var(--gray-bg)
}
 #zingblog-pro-about-section{
    flex-wrap:wrap;
    padding:40px 0
}
 .about-section .Image{
    display:flex;
    justify-content:space-between;
    align-items:center;
    width:calc(100% - $(sidebar.width + 30px))
}
 .footer-info{
    flex:1
}
 .footer-info .title{
    font-size:15px;
    color:var(--title-color);
    text-transform:uppercase;
    margin:0 0 10px
}
 .footer-logo{
    padding:0 30px 0 0
}
 .rtl .footer-logo{
    padding:0 0 0 30px
}
 .footer-logo img{
    display:block;
    width:auto;
    height:auto;
    max-height:40px
}
 .footer-info .image-caption{
    font-size:14px;
    color:var(--text-color);
    margin:0
}
 .footer-info .image-caption a{
    color:var(--ftitle-color)
}
 .footer-info .image-caption a:hover{
    color:var(--title-hover-color)
}
 .about-section .LinkList{
    width:$(sidebar.width);
    display:flex;
    align-items:center;
    justify-content:flex-end;
    margin:0
}
 .about-section ul.social-icons{
    display:flex;
    flex-wrap:wrap
}
 .about-section .social-icons li{
    margin:0 0 0 10px
}
 .rtl .about-section .social-icons li{
    margin:0 10px 0 0
}
 .about-section .social-icons a{
    display:flex;
    width:34px;
    height:34px;
    background-color:var(--gray-bg);
    font-size:16px;
    color:var(--title-color);
    align-items:center;
    justify-content:center
}
 .about-section .social-icons .rss a,.about-section .social-icons .email a,.about-section .social-icons .external-link a{
    font-size:20px
}
 .about-section .social-icons a:hover{
    color:#fff
}
 .footer-bar{
    background-color:var(--footerbar-bg);
    color:var(--footerbar-color);
    padding:20px 0
}
 .footer-bar .footer-copyright{
    font-size:14px;
    font-weight:400;
    margin:0
}
 .footer-bar .footer-copyright a{
    color:var(--footerbar-color)
}
 .footer-bar .footer-copyright a:hover{
    color:var(--footerbar-hover-color)
}
 #footer-menu{
    position:relative;
    display:block;
    margin:0
}
 .footer-menu ul{
    display:flex;
    flex-wrap:wrap
}
 .footer-menu ul li a{
    font-size:14px;
    color:var(--footerbar-color);
    padding:0;
    margin:0 0 0 25px
}
 .rtl .footer-menu ul li a{
    margin:0 25px 0 0
}
 #footer-menu ul li a:hover{
    color:var(--footerbar-hover-color)
}
 #hidden-widgets-wrap,.hidden-widgets{
    display:none;
    visibility:hidden
}
 #back-top{
    display:flex;
    align-items:center;
    justify-content:center;
    position:fixed;
    bottom:20px;
    right:20px;
    width:34px;
    height:34px;
    background-color:var(--button-bg);
    font-size:24px;
    color:var(--button-color);
    z-index:50;
    opacity:0;
    visibility:hidden;
    transition:visibility .17s ease,opacity .17s ease
}
 .rtl #back-top{
    right:auto;
    left:20px
}
 #back-top:before{
    content:'\e5ce';
    font-family:'Material Icons Round';
    font-weight:400
}
 #back-top.show{
    opacity:1;
    visibility:visible
}
 #back-top:hover{
    background-color:var(--button-hover-bg);
    color:var(--button-hover-color)
}
 .is-error #main-wrapper{
    width:100%
}
 .is-error #sidebar-wrapper{
    display:none
}
 .errorWrap{
    color:var(--title-color);
    text-align:center;
    padding:60px 0
}
 .errorWrap h3{
    font-size:160px;
    color:var(--title-color);
    line-height:1;
    margin:0 0 25px
}
 .errorWrap h4{
    font-size:27px;
    color:var(--title-color);
    margin:0 0 25px
}
 .errorWrap p{
    color:var(--text-color);
    font-size:15px;
    margin:0 0 15px
}
 .errorWrap a{
    display:inline-block;
    height:34px;
    background-color:var(--button-bg);
    font-size:14px;
    color:var(--button-color);
    font-weight:400;
    line-height:34px;
    padding:0 30px;
    margin:15px 0 0
}
 .errorWrap a:hover{
    background-color:var(--button-hover-bg);
    color:var(--button-hover-color)
}
 .cookie-choices-info{
    display:none;
    visibility:hidden;
    opacity:0
}
 .cookie-consent{
    display:none;
    position:fixed;
    bottom:20px;
    left:20px;
    width:300px;
    background-color:var(--cookie-bg);
    z-index:1020;
    padding:20px;
    visibility:hidden;
    opacity:0;
    border-radius:var(--radius);
    box-shadow:0 0 10px rgba(0,0,0,0.1);
    transition:visibility .35s ease,opacity .35s ease,transform .35s ease
}
 .rtl .cookie-consent{
    left:unset;
    right:20px
}
 .cookie-consent.is-visible{
    visibility:visible;
    opacity:1
}
 .consent-text{
    display:block;
    font-size:14px;
    color:var(--cookie-color);
    margin:0 0 15px
}
 .consent-text a{
    color:var(--main-color);
    text-decoration:underline
}
 .consent-button{
    display:inline-block;
    height:34px;
    background-color:var(--button-bg);
    font-size:14px;
    color:var(--button-color);
    font-weight:400;
    line-height:34px;
    padding:0 20px
}
 .consent-button:hover{
    background-color:var(--button-hover-bg);
    color:var(--button-hover-color)
}
 ins.adsbygoogle-noablate[data-anchor-shown="true"]{
    z-index:990!important
}
 #content-wrapper > .google-auto-placed,#content-wrapper .container > .google-auto-placed{
    display:none!important
}
 .CSS_LIGHTBOX{
    z-index:999999!important
}
 .CSS_LIGHTBOX_BG_MASK{
    background-color:rgba(0,0,0,0.9)!important;
    opacity:1!important;
