     .cookie-consent{
        right:0!important;
        left:0!important;
        bottom:0;
        width:100%;
        padding:20px;
        border-radius:0
    }
     a.ads-here{
        height:65px
    }
     .sidebar a.ads-here{
        height:180px
    }
}
 @media only screen and (max-width: 480px) {
     .grid-item .entry-image-wrap{
        height:115px
    }
     .grid2-item .entry-image-wrap{
        height:115px
    }
     .video-grid .entry-image-wrap{
        height:115px
    }
     .video-style .video-grid .entry-image-wrap{
        height:105px
    }
     .item-post h1.entry-title{
        font-size:29px
    }
     .related-item .entry-image-wrap{
        height:115px
    }
     .side3-item .entry-image-wrap{
        height:115px
    }
}
 @media only screen and (max-width: 380px) {
     #featured .widget-content{
        min-height:220px
    }
     .featured-item.item-0{
        height:200px
    }
     .featured-item .entry-title,.type-feat1 .featured-item.item-1 .entry-title,.type-feat3 .featured-item .entry-title{
        font-size:14px
    }
     .featured-item.item-0 .entry-title,.type-feat3 .featured-item.item-0 .entry-title{
        font-size:21px
    }
     .featured-grid{
        height:130px
    }
     .block-items .item-0 .entry-image-wrap{
        height:180px
    }
     .grid-item .entry-image-wrap{
        height:100px
    }
     .grid2-item .entry-image-wrap{
        height:100px
    }
     .col-item .entry-inner{
        height:180px
    }
     .video-items .cs .entry-inner{
        height:180px
    }
     .video-style .video-items .cs .entry-inner{
        height:160px
    }
     .video-grid .entry-image-wrap{
        height:100px
    }
     .video-style .video-grid .entry-image-wrap{
        height:90px
    }
     .index-post .entry-image-wrap{
        height:180px
    }
     .item-post h1.entry-title{
        font-size:27px
    }
     .item-post .entry-meta .align-right{
        display:none
    }
     .templateify-toc-inner{
        min-width:100%
    }
     .share-links span{
        display:none
    }
     .share-links .has-span a{
        width:40px;
        justify-content:center
    }
     .share-links .has-span a:before{
        width:100%;
        background-color:transparent
    }
     .related-item .entry-image-wrap{
        height:100px
    }
     .FeaturedPost .entry-inner{
        height:180px
    }
     .side-item .entry-inner{
        height:180px
    }
     .side3-item .entry-image-wrap{
        height:100px
    }
     .share-links .pinterest-p{
        display:block
    }
}
 @media only screen and (max-width: 340px) {
     #slide-menu{
        width:100%
    }
     .errorWrap h3{
        font-size:110px
    }
     .errorWrap h4{
        font-size:27px
    }
}

b:if.b:template-skin:
html,body#layout #outer-wrapper,body#layout .row{
    width:auto;
    padding:0
}
 body#layout{
    position:relative;
    width:auto;
    max-width:100%;
    background-color:#fff;
    padding:95px 5px 0;
    margin:0 0 0 1px;
    border-width:1px 0 0;
    border-color:#eceff1
}
 body#layout:before{
    content:'ZingBlog - Version - 1.0';
    position:absolute;
    top:0;
    left:5px;
    right:5px;
    height:95px;
    font-family:Roboto,sans-serif;
    font-size:23px;
    color:#263238;
    line-height:95px;
    text-align:center
}
 body#layout div.section{
    display:block;
    background-color:#eceff1!important;
    margin:0 5px 10px!important;
    padding:16px 16px 18px!important;
    border:0
}
 body#layout .no-items.section{
    display:block
}
 body#layout .section h4{
    font-size:14px;
    color:#263238;
    text-transform:uppercase;
    margin:0
}
 body#layout .section h4:after{
    text-transform:initial;
    color:#757575;
    font-weight:400
}
 body#layout .add_widget a{
    color:#4385f5!important
}
 body#layout .widget-wrap3{
    overflow:hidden
}
 body#layout .widget-content{
    width:auto;
    max-width:none;
    max-height:none;
    margin:0;
    border:1px solid #e7e7e8;
    border-left:0
}
 body#layout .locked-widget .widget-content{
    border-left:1px solid #4385f5
}
 body#layout .locked-widget .widget-content:hover{
    border-left-color:#33a453
}
 body#layout div.layout-title{
    color:#757575
}
 body#layout .widget .widget-content a.editlink{
    border-radius:2px
}
 body#layout .visibility .editlink{
    background:#4385f5 url(https://1.bp.blogspot.com/--z1wepFalfQ/YOObl8avCFI/AAAAAAAAAE8/Z-iC0j0LLpo7u2ZpHvW0hGaHhBOvVYYaQCLcBGAsYHQ/s48/edit.png) no-repeat center!important;
    background-size:20px!important
}
 body#layout .visibility .editlink:hover{
    background-color:#33a453!important
}
 body#layout .draggable-widget .widget-wrap2{
    background:#4385f5 url(https://1.bp.blogspot.com/-ciJD7MVmo10/YORQlzt9a1I/AAAAAAAAAFk/L4fK5cgelFoWX9rZvGFKZdr1d_RM9kfjACLcBGAsYHQ/s68/drag.png) no-repeat 4px 50%!important;
    background-size:4px auto!important
}
 body#layout .draggable-widget .widget-wrap1:hover .widget-wrap2{
    background-color:#33a453!important
}
 body#layout .visibility .layout-widget-state.visible{
    background-image:url(https://1.bp.blogspot.com/-aPoC3YxQo6g/YOOeDVSsJqI/AAAAAAAAAFM/oyvPLSJVIRQpAu-g0gZL89g5Caq4_4DeQCLcBGAsYHQ/s48/visibility_on.png)!important;
    background-size:24px!important
}
 body#layout .visibility .layout-widget-state.not-visible{
    background-image:url(https://1.bp.blogspot.com/-x_kkTMRQfHs/YOOeMUjTE8I/AAAAAAAAAFQ/RRj6YLBNuMEHwTB_81304fCxy8dl7h46gCLcBGAsYHQ/s48/visibility_off.png)!important;
    background-size:24px!important;
    opacity:1
}
 body#layout div.layout-widget-description{
    display:none;
    font-size:11px;
    line-height:1.2em
}
 body#layout #theme-options,body#layout #main-menu .widget{
    display:block!important
}
 body#layout div.templateify-panel{
    background-color:rgba(67,133,245,0.15)!important;
    overflow:hidden!important
}
 body#layout .templateify-panel .widget{
    float:left;
    width:32.66%;
    margin-right:1%
}
 body#layout .templateify-panel .widget-content{
    border-color:#d5e3fc!important
}
 body#layout .templateify-panel .HTML{
    margin-right:0
}
 body#layout .templateify-panel div.layout-widget-description,body#layout .flex-right,body#layout #nav-search-wrap{
    display:none
}
 body#layout #topbar{
    overflow:hidden!important
}
 body#layout #topbar .widget{
    float:left;
    width:49.5%;
    margin-right:1%
}
 body#layout #topbar #LinkList202{
    margin-right:0
}
 body#layout .flex-left{
    display:flex
}
 body#layout .main-logo,body#layout .zingblog-pro-main-nav{
    width:50%
}
 body#layout #content-wrapper{
    padding:0;
    margin:0
}
 body#layout #content-wrapper > .container{
    display:flex;
    margin:0
}
 body#layout #main-wrapper{
    width:67%;
    padding:0
}
 body#layout #sidebar-wrapper{
    width:33%;
    padding:0
}
 body#layout #custom-ads{
    display:flex
}
 body#layout #custom-ads .section{
    width:50%
}
 body#layout .footer-widgets{
    display:flex
}
 body#layout .footer-widgets .section{
    width:100%
}
 body#layout #zingblog-pro-about-section{
    overflow:hidden!important
}
 body#layout #zingblog-pro-about-section .widget{
    float:left;
    width:49.5%;
    margin-right:1%
}
 body#layout #zingblog-pro-about-section .LinkList{
    margin-right:0
}
 body#layout .footer-bar .container{
    display:flex
}
 body#layout #footer-menu,body#layout #footer-copyright{
    width:50%
}
 body#layout .section > h4:after{
    font-size:12px
}
 body#layout #templateify-panel > h4:after{
    content:' - Default Thumbnail, Date Format, Translate Months and More'
}
 body#layout #topbar > h4:after{
    content:' - Top Links and Social Icons'
}
 body#layout #main-logo > h4:after{
    content:' - Recommended Height (40px)'
}
 body#layout #zingblog-pro-main-nav > h4:after{
    content:' - Menu Links, Sub Links and Mega Menu'
}
 body#layout #header-ads > h4:after{
    content:' - by Custom HTML, Adsense or Image'
}
 body#layout #ticker > h4:after{
    content:' - by Popular Posts, Recents or Label'
}
 body#layout #featured > h4:after{
    content:' - by Popular Posts, Recents or Label'
}
 body#layout .content-section > h4:after{
    content:' - by Most Recents, Label or AD Gadget (Adsense, HTML)'
}
 body#layout #main > h4:after{
    content:' - Default Blog Posts, AdSense In-Feed, Comments and More'
}
 body#layout #zingblog-pro-main-before-ad > h4:after{
    content:' - Before Post Content (Post Page)'
}
 body#layout #zingblog-pro-main-after-ad > h4:after{
    content:' - After Post Content (Post Page)'
}
 body#layout #zingblog-pro-related-posts > h4:after{
    content:' - Exclusive Related Posts (No Duplicate Posts)'
}
 body#layout #zingblog-pro-post-footer-ads > h4:after{
    content:' - After Related Posts (Post Page)'
}
 body#layout #sidebar > h4:after{
    content:' - Default Gadgets'
}
 body#layout #footer-ads > h4:after{
    content:' - by Custom HTML, Adsense or Image'
}
 body#layout .footer-section > h4:after{
    content:' - Default Gadgets'
}
 body#layout #zingblog-pro-about-section > h4:after{
    content:' - Site Logo, Description and Social Icons'
}
 body#layout #footer-copyright > h4:after{
    content:' - Custom Credits'
}
 body#layout #footer-menu > h4:after{
    content:' - Footer Links'
}
 body#layout #cookie-consent-section > h4:after{
    content:' - Native Cookie Consent Plugin'
}
 body#layout #hidden-widgets{
    display:none!important
}

